const logic={reload:(mag,reserve,max)=>{const amount=Math.min(Math.max(0,max-mag),Math.max(0,reserve));return {mag:mag+amount,reserve:reserve-amount}},damage:(hp,shield,value)=>{const absorb=Math.min(shield,Math.max(0,value));return {hp:Math.max(0,hp-value+absorb),shield:shield-absorb}},validConfig:c=>Number.isInteger(c.capacity)&&c.capacity>=1&&c.capacity<=12&&Number.isFinite(c.duration)&&c.duration>=1&&c.duration<=30,grenadeCount:(store,id)=>Number.isInteger(store.grenadeQuantities?.[id])?clamp(store.grenadeQuantities[id],0,10):2};window.blockforgeGameLogic={logic,WEAPONS,grenadeStats};
let store={balance:0,owned:['steve','m4','frag'],equipped:{characters:'steve',skins:null,clothes:[],weapons:'m4',grenades:'frag',abilities:null,potions:null}},saved={};try{const s=JSON.parse(localStorage.getItem('blockforge-store-v3'));if(s&&Array.isArray(s.owned)&&s.equipped)store={...store,...s};saved=JSON.parse(localStorage.getItem('blockforge-match-config'))||{}}catch(e){}const owned=id=>store.owned.includes(id)||['steve','m4','frag'].includes(id);let outfit={...store.equipped,clothes:Array.isArray(store.equipped.clothes)?store.equipped.clothes:[]};for(const k of ['characters','weapons','grenades'])if(!byId(outfit[k])||!owned(outfit[k]))outfit[k]={characters:'steve',weapons:'m4',grenades:'frag'}[k];for(const k of ['skins','abilities','potions'])if(!byId(outfit[k])||!owned(outfit[k]))outfit[k]=null;let chosenTeam='blue';let config={mode:modes.some(m=>m.id===saved.mode)?saved.mode:'teams',map:maps.some(m=>m.id===saved.map)?saved.map:'neon',capacity:clamp(Number(saved.capacity)||8,1,12),duration:clamp(Number(saved.duration)||10,1,30),privacy:saved.privacy==='public'?'public':'private',session:'practice',roomId:typeof saved.roomId==='string'?saved.roomId:'FRONTLINE'};if(!maps.find(x=>x.id===config.map).modes.includes(config.mode))config.map=maps.find(x=>x.modes.includes(config.mode)).id;
function stats(id){const p=byId(id)||byId('steve');return {hp:id==='heavy'?140:id==='cyborg'?125:id==='paladin'?130:id==='scout'?90:100,speed:id==='heavy'?4:id==='scout'?6.2:id==='alex'?5.8:id==='pilot'?6:5.2,shield:id==='paladin'?20:0,passive:p.pro||'Equilibrado',skill:outfit.abilities||({medic:'heal',alex:'speed',scout:'dash',ranger:'shield',frost:'cleanse',shadow:'cloak',cyborg:'shield',engineer:'cleanse',sniperop:'focus',heavy:'barrier',pilot:'dash',paladin:'barrier',spectre:'cloak'}[id]||'focus')}}
$('teams').innerHTML=teamIds.map(id=>'<button class="team '+(id===chosenTeam?'active':'')+'" data-team="'+id+'" style="--t:#'+teamColors[id].toString(16)+'">'+teamNames[id]+'</button>').join('');document.querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>{chosenTeam=b.dataset.team;document.querySelectorAll('[data-team]').forEach(x=>x.classList.toggle('active',x===b))});$('modeSelect').innerHTML=modes.map(m=>'<option value="'+m.id+'">'+esc(m.name)+'</option>').join('');$('characterSelect').innerHTML=catalog.filter(x=>x.cat==='characters'&&owned(x.id)).map(x=>'<option value="'+x.id+'">'+esc(x.name)+' · Nivel '+x.level+'</option>').join('');$('characterSelect').value=outfit.characters;$('modeSelect').value=config.mode;$('minutes').innerHTML=[5,10,16,30].map(n=>'<option value="'+n+'">'+n+' minutos</option>').join('');$('minutes').value=config.duration;$('privacy').value=config.privacy;if(saved.players?.length)$('name').value=saved.players[0].name||'Operador';
