function movePlayer(dt){if(!player.alive)return;const forward=(keys.has('w')||keys.has('ArrowUp')?1:0)-(keys.has('s')||keys.has('ArrowDown')?1:0)-stick.z,side=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0)+stick.x;let dx=Math.sin(yaw)*forward+Math.cos(yaw)*side,dz=-Math.cos(yaw)*forward+Math.sin(yaw)*side;const len=Math.hypot(dx,dz);const sprint=(keys.has('Shift')||Math.hypot(stick.x,stick.z)>.9)&&len>0&&stamina>4&&!aiming;let speed=stats(outfit.characters).speed*(sprint?1.5:1)*(aiming?.6:1)*(activeSkill==='speed'?1.2:1)*(activeSkill==='barrier'?.75:1)*(player.slowUntil>timeNow?.55:1);if(len>0){dx=dx/Math.max(1,len)*speed*dt;dz=dz/Math.max(1,len)*speed*dt;moveBody(player.pos,dx,dz);walkTime+=dt*(sprint?13:9)}stamina=clamp(stamina+(sprint?-19:12)*dt,0,100);const floor=groundAt(player.pos.x,player.pos.z,player.pos.y);if(grounded&&player.pos.y-floor>.45)grounded=false;if(!grounded){vy-=18*dt;player.pos.y+=vy*dt;if(player.pos.y<=floor){player.pos.y=floor;vy=0;grounded=true}}else player.pos.y=floor;camera.position.set(player.pos.x,player.pos.y+1.7+(len>.1?Math.sin(walkTime)*.025:0),player.pos.z);camera.rotation.set(pitch+recoil*.25,-yaw,0);camera.fov=aiming?(currentWeapon==='sniper'?32:52):72;camera.updateProjectionMatrix();recoil=Math.max(0,recoil-dt*.6);if(fp){const reloading=reloadEnd>timeNow;fp.position.set(aiming?-.14:0,len>.1?Math.sin(walkTime)*.007:0,recoil);fp.rotation.z=reloading?Math.sin((reloadEnd-timeNow)*5)*.22:0;fp.rotation.x=reloading?.35:fp.userData.throwUntil>timeNow?-.55:0;if(muzzle&&timeNow>muzzle.userData.until){muzzle.visible=false;fp.userData.flashlight.intensity=0}}if(avatar){avatar.rotation.y=Math.sin(timeNow*.5)*.2;avatar.scale.y=grounded?1:1.03;const ar=avatar.userData.arms;ar.left.joint.rotation.x=len>.1?Math.sin(walkTime)*.6:0;ar.right.joint.rotation.x=-1.1+(len>.1?Math.sin(walkTime)*.12:0);avatar.position.y=grounded?0:.08;avatarRenderer.render(avatarScene,avatarCamera)}}
