function projectileUpdate(dt){for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];if(p.type==='grenade')p.vel.y-=9.8*dt;const travel=p.vel.clone().multiplyScalar(dt),dist=travel.length();ray.set(p.pos,travel.clone().normalize());ray.far=dist+.12;const h=ray.intersectObject(world,true).find(x=>x.distance>.01);if(h){if(p.type==='rocket'){explode(h.point,'rocket',p.owner);removeProjectile(i);continue}p.pos.copy(h.point).addScaledVector(h.face.normal.clone().transformDirection(h.object.matrixWorld),.15);p.vel.reflect(h.face.normal.clone().transformDirection(h.object.matrixWorld)).multiplyScalar(.38)}else p.pos.add(travel);p.mesh.position.copy(p.pos);p.mesh.rotation.x+=dt*4;if(p.type==='rocket'){const enemyActor=actors.find(a=>a.alive&&enemy(player,a)&&a.pos.distanceTo(p.pos)<1.4);if(enemyActor){explode(p.pos,'rocket',p.owner);removeProjectile(i);continue}}if(timeNow>=p.expires||(p.type==='rocket'&&p.pos.distanceTo(player.pos)>85)){explode(p.pos,p.type==='rocket'?'rocket':p.grenade,p.owner);removeProjectile(i)}}for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.life-=dt;if(e.mesh.material)e.mesh.material.opacity=Math.max(0,e.life/e.max)*.5;if(e.expand)e.mesh.scale.setScalar(1+(1-e.life/e.max)*.5);if(e.life<=0){scene.remove(e.mesh);dispose(e.mesh);effects.splice(i,1)}}for(let i=zones.length-1;i>=0;i--){const z=zones[i];if(timeNow>z.until){zones.splice(i,1);continue}if(timeNow>z.next){z.next=timeNow+1;for(const a of [player,...actors])if(a.alive&&enemy(z.owner,a)&&a.pos.distanceTo(z.pos)<z.radius){if(a===player)takeDamage(z.damage/3,z.owner);else hitActor(a,z.damage/3,z.owner)}}}}
