$('quality').value=qualityMode;function applyQuality(){if(!renderer)return;const ratio=qualityMode==='high'?Math.min(devicePixelRatio,1.75):qualityMode==='balanced'?Math.min(devicePixelRatio,1.25):.8;renderer.setPixelRatio(ratio);renderer.shadowMap.enabled=qualityMode==='high';renderer.setSize(innerWidth,innerHeight);if(avatarRenderer)avatarRenderer.setPixelRatio(qualityMode==='low'?.7:1);if(setupRenderer)setupRenderer.setPixelRatio(1)}$('quality').onchange=()=>{qualityMode=$('quality').value;applyQuality()};
const oldFrame=frame;frame=function(now){const interval=qualityMode==='low'?1000/30:1000/60;if(now-lastRender<interval-.5){requestAnimationFrame(frame);return}const dt=Math.min((now-lastRender)/1000,.05);lastRender=now;ragdollStep(dt);effects.forEach(e=>{if(e.velocity){e.velocity.y-=12*dt;e.mesh.position.addScaledVector(e.velocity,dt)}});performanceFrames++;if(now-performanceTime>1000){fpsValue=Math.round(performanceFrames*1000/(now-performanceTime));performanceTime=now;performanceFrames=0}oldFrame(now)};
