const onlineBody=body;body=function(eq,color){const g=onlineBody(eq,color);g.userData.legs={};for(const [key,x] of [['left',-.185],['right',.185]]){const joint=new THREE.Group();joint.position.set(x,.8,0);const parts=g.children.filter(o=>o.isMesh&&Math.abs(o.position.x-x)<.01&&o.position.y<.85);parts.forEach(o=>{g.remove(o);o.position.sub(joint.position);joint.add(o)});g.add(joint);g.userData.legs[key]=joint}return g};
