function bloodEffect(pos){const red=0xa91d29;for(let i=0;i<(qualityMode==='low'?7:16);i++){const mesh=new THREE.Mesh(new THREE.SphereGeometry(.045,4,3),new THREE.MeshBasicMaterial({color:red,transparent:true}));mesh.position.copy(pos).add(new THREE.Vector3(0,1,0));scene.add(mesh);effects.push({mesh,life:.8,max:.8,velocity:new THREE.Vector3((Math.random()-.5)*4,Math.random()*3,(Math.random()-.5)*4)})}const puddle=new THREE.Mesh(new THREE.CylinderGeometry(.3,.3,.006,12),new THREE.MeshBasicMaterial({color:red,transparent:true,opacity:.55,depthWrite:false}));puddle.position.set(pos.x,groundAt(pos.x,pos.z,pos.y)+.009,pos.z);scene.add(puddle);effects.push({mesh:puddle,life:5,max:5})}
const labels=new Map();function playerLabels(){if(!camera||!player)return;const root=$('playerLabels');for(const a of actors){let label=labels.get(a.id);if(!label){label=document.createElement('div');label.className='player-label';const name=document.createElement('span'),life=document.createElement('b'),track=document.createElement('div'),fill=document.createElement('i');name.className='player-label-name';life.className='player-label-life';track.className='player-label-track';track.appendChild(fill);label.appendChild(name);label.appendChild(life);label.appendChild(track);root.appendChild(label);label.parts={name,life,fill};labels.set(a.id,label)}const pos=a.pos.clone().add(new THREE.Vector3(0,2.05,0)),view=pos.clone().project(camera),front=pos.clone().sub(camera.position).dot(camera.getWorldDirection(new THREE.Vector3()))>0;label.style.display=a.alive&&front&&view.z>=-1&&view.z<=1&&Math.abs(view.x)<1&&Math.abs(view.y)<1?'block':'none';label.style.left=(view.x*.5+.5)*innerWidth+'px';label.style.top=(-view.y*.5+.5)*innerHeight+'px';label.parts.name.textContent=a.name;label.parts.life.textContent=Math.ceil(a.hp)+' / '+a.maxHp;label.parts.fill.style.width=Math.max(0,a.hp/a.maxHp*100)+'%';label.style.borderColor='#'+teamColors[a.team].toString(16)}for(const [id,label] of labels)if(!actors.some(a=>a.id===id)){label.remove();labels.delete(id)}}
