table=function(){if(!player)return;const rows=[player,...actors].sort((a,b)=>b.points-a.points||b.kills-a.kills||a.deaths-b.deaths);$('scoreTable').innerHTML=rows.map((a,i)=>'<tr><td>'+(i+1)+'</td><td style="color:#'+teamColors[a.team].toString(16)+'">'+esc(a.name)+(a.id===player.id?' · Tú':'')+'</td><td>'+(a.alive?Math.ceil(a.hp)+' / '+a.maxHp:'Reapareciendo')+'</td><td>'+a.kills+'</td><td>'+a.deaths+'</td><td>'+a.points+'</td></tr>').join('')};
